document.addEventListener("DOMContentLoaded",init);let currentSlug=null;async function init(){currentSlug=getQueryParam("store")||localStorage.getItem("skiri_active_store");if(!currentSlug){render();return}try{localStorage.setItem("skiri_active_store",currentSlug)}catch(e){}document.getElementById("back-to-store-link").href=`store.html?store=${encodeURIComponent(currentSlug)}`;const hideOverlay=showLoadingOverlay();const request=Api.get("getStorePublicInfo",{storeSlug:currentSlug});window.__criticalReady=request;window.__storeInfoPromise=request.then(r=>r&&r.ok&&r.store?{storeName:r.store.storeName,logoUrl:r.store.logoUrl}:null);const res=await request;hideOverlay();if(res.ok){window.__storeOpen=res.store.isOpen!==false;document.getElementById("store-name-tagline").textContent=`Your cart — ${shortStoreName(res.store.storeName)}`;if(res.store.logoUrl){const logoImg=document.getElementById("store-logo-img");logoImg.src=optimizedImageUrl(res.store.logoUrl,IMG_W.logo);logoImg.alt=res.store.storeName;logoImg.classList.remove("hidden")}if(res.store.phone){const phoneLine=document.getElementById("store-phone-line");phoneLine.textContent=res.store.phone;phoneLine.classList.remove("hidden")}document.getElementById("store-delivery-icons").innerHTML=renderDeliveryIcons({truck:res.store.deliveryTruck,ship:res.store.deliveryShip,airCargo:res.store.deliveryAirCargo,pickPay:res.store.deliveryPickPay,truckCost:res.store.deliveryTruckCost,shipCost:res.store.deliveryShipCost,airCargoCost:res.store.deliveryAirCargoCost})}document.getElementById("cart-items").addEventListener("click",onCartClick);document.getElementById("cart-items").addEventListener("input",onCartInput);document.getElementById("cart-items").addEventListener("change",onCartChange);render()}function render(){const emptyEl=document.getElementById("cart-empty");const contentEl=document.getElementById("cart-content");const itemsEl=document.getElementById("cart-items");const liveEl=document.getElementById("cart-live");const cart=currentSlug?Cart.getCart(currentSlug):[];if(cart.length===0){emptyEl.classList.remove("hidden");contentEl.classList.add("hidden");liveEl.textContent="Your cart is empty.";return}emptyEl.classList.add("hidden");contentEl.classList.remove("hidden");itemsEl.innerHTML=cart.map(line=>`\n      <div class="cart-line${hasBulk(line)?" cart-line--bulk":""}" data-variant-id="${escapeHtml(line.variantId)}">\n        <div class="cart-line-info">\n          <strong>${escapeHtml(line.label)}</strong><br>\n          <span class="helper-text cart-line-price">${linePriceHtml(line)}</span>\n        </div>\n        <label class="sr-only" for="qty-${escapeHtml(line.variantId)}">Quantity for ${escapeHtml(line.label)}</label>\n        <input id="qty-${escapeHtml(line.variantId)}" class="cart-line-qty" type="number" min="${Cart.minQtyOf(line)}" value="${line.qty}" inputmode="numeric">\n        <strong class="cart-line-total">${formatMoney(Cart.lineTotal(line))}</strong>\n        <button type="button" class="btn btn-danger btn-small" data-action="remove">Remove</button>\n        ${hasBulk(line)?`<p class="helper-text cart-line-bulk">${escapeHtml(lineBulkNotes(line))}</p>`:""}\n      </div>\n    `).join("");document.getElementById("cart-total").textContent=formatMoney(Cart.getTotal(currentSlug));liveEl.textContent=`${Cart.getItemCount(currentSlug)} item(s) in your cart.`}function linePriceHtml(line){const unit=Cart.unitPriceOf(line);let html=`${formatMoney(unit)} each`;if(unit<Number(line.unitPrice))html+=` <span class="cart-bulk-tag">Bulk price</span> <s class="cart-normal-price">${formatMoney(line.unitPrice)}</s>`;return html}function hasBulk(line){return Array.isArray(line.tiers)&&line.tiers.length>0||Cart.minQtyOf(line)>1}function lineBulkNotes(line){const parts=[];const next=Cart.nextTierOf(line);if(next)parts.push(`Buy ${Number(next.minQty)}+ for ${formatMoney(next.price)} each`);if(Cart.minQtyOf(line)>1)parts.push(`Minimum order ${Cart.minQtyOf(line)}`);return parts.join(" · ")}function onCartClick(e){const btn=e.target.closest('[data-action="remove"]');if(!btn)return;const variantId=btn.closest(".cart-line").dataset.variantId;Cart.removeItem(currentSlug,variantId);render()}function onCartInput(e){if(!e.target.classList.contains("cart-line-qty"))return;const qty=parseInt(e.target.value,10);if(!(qty>=1))return;const line=e.target.closest(".cart-line");const variantId=line.dataset.variantId;const current=Cart.getCart(currentSlug).find(l=>l.variantId===variantId);if(current&&qty<Cart.minQtyOf(current))return;const updatedCart=Cart.updateQty(currentSlug,variantId,qty);const updatedLine=updatedCart.find(l=>l.variantId===variantId);if(!updatedLine)return;line.querySelector(".cart-line-total").textContent=formatMoney(Cart.lineTotal(updatedLine));line.querySelector(".cart-line-price").innerHTML=linePriceHtml(updatedLine);const notes=line.querySelector(".cart-line-bulk");if(notes)notes.textContent=lineBulkNotes(updatedLine);document.getElementById("cart-total").textContent=formatMoney(Cart.getTotal(currentSlug));document.getElementById("cart-live").textContent=`${Cart.getItemCount(currentSlug)} item(s) in your cart.`}function onCartChange(e){if(!e.target.classList.contains("cart-line-qty"))return;const variantId=e.target.closest(".cart-line").dataset.variantId;const qty=Math.max(0,parseInt(e.target.value,10)||0);Cart.updateQty(currentSlug,variantId,qty);render()}